<div {{ $attributes->merge(['class' => 'space-y-3 empty:hidden']) }}>@foreach (['success', 'error', 'warning', 'info'] as $type)@if (session($type))<x-alert :type="$type" dismissible>{{ session($type) }}</x-alert>@endif @endforeach @if ($errors->any() && ! session('error'))<x-alert type="error" dismissible>@if ($errors->count() === 1){{ $errors->first() }}@else<div class="font-medium">{{ __('Please check the form:') }}</div><ul class="mt-1 list-disc ps-5">@foreach ($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif</x-alert>@endif</div>
